# roads are dense polylines now: find the segment by binary search (was a linear scan)
rep("function posAt(map,d,r){const R=map.routes?map.routes[r||0]:map;const segs=R.segs,pts=R.pts;if(d<=0){const s=segs[0];return{x:s.a.x,y:s.a.y};}for(const s of segs){if(d<=s.start+s.len){const t=(d-s.start)/s.len;return{x:s.a.x+(s.b.x-s.a.x)*t,y:s.a.y+(s.b.y-s.a.y)*t};}}const l=pts[pts.length-1];return{x:l.x,y:l.y};}",
    "function posAt(map,d,r){const R=map.routes?map.routes[r||0]:map;const segs=R.segs,pts=R.pts;if(d<=0){const s=segs[0];return{x:s.a.x,y:s.a.y};}let lo=0,hi=segs.length-1;if(d>=segs[hi].start+segs[hi].len){const l=pts[pts.length-1];return{x:l.x,y:l.y};}while(lo<hi){const m=(lo+hi)>>1;if(segs[m].start+segs[m].len<d)lo=m+1;else hi=m;}const s=segs[lo],t=(d-s.start)/s.len;return{x:s.a.x+(s.b.x-s.a.x)*t,y:s.a.y+(s.b.y-s.a.y)*t};}", label='posat')
